export const ALL_KHALIFA_PROFILES = Object.values(KHULAFA_PROFILES);

export function getKhalifaProfileBySlug(slug: string): KhalifaProfile | undefined {
  return KHULAFA_PROFILES[slug];
}

export function getKhalifaProfileNavigation(slug: string): {
  prev?: { slug: string; nameUrdu: string; nameEn: string };
  next?: { slug: string; nameUrdu: string; nameEn: string };
} {
  const list = ALL_KHALIFA_PROFILES;
  const currentIndex = list.findIndex((p) => p.slug === slug);
  if (currentIndex === -1) return {};

  const prev = currentIndex > 0 ? list[currentIndex - 1] : undefined;
  const next = currentIndex < list.length - 1 ? list[currentIndex + 1] : undefined;

  return {
    prev: prev ? { slug: prev.slug, nameUrdu: prev.nameUrdu, nameEn: prev.nameEn } : undefined,
    next: next ? { slug: next.slug, nameUrdu: next.nameUrdu, nameEn: next.nameEn } : undefined,
  };
}
